import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imageUrl = config?.assets?.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  const map = ctx.textureLoader(imageUrl);
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
  }

  const uvNode = uv();

  // engineered gradient overlay: ink -> surface, subtle vertical falloff, no soft blur
  const ink = new THREE.Color('#16161d');
  const surface = new THREE.Color('#0b0b10');

  const gradientMix = uvNode.y.oneMinus();
  const gradientColor = mix(vec4(surface.r, surface.g, surface.b, 1.0), vec4(ink.r, ink.g, ink.b, 1.0), gradientMix);

  let colorNode;
  if (map) {
    const texColor = texture(map, uvNode);
    // composite texture over engineered gradient, texture alpha driven blend
    colorNode = mix(gradientColor, texColor, texColor.a);
  } else {
    colorNode = gradientColor;
  }

  material.colorNode = colorNode;

  const mesh = new THREE.Mesh(geometry, material);

  const pos = config?.scenePosition?.position || [0, -2.85, 0.2];
  const rot = config?.scenePosition?.rotation || [0, 0, 0];
  const scl = config?.scenePosition?.scale || [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  mesh.name = 'home-cta-decor-plane';

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) {
      map.dispose();
    }
  };

  return mesh;
}
